function normalizeV03(input){const x=clone(input),report=[];x.schemaVersion=VERSION;x.book='PSA';x.psalm=+x.psalm||1;x.revision=x.revision||sourceRevision();x.psalmStatus=x.psalmStatus||'not-started';x.segments=Array.isArray(x.segments)?x.segments:initialSegments();['parallelGroups','components','structures','notes'].forEach(k=>{if(!Array.isArray(x[k]))x[k]=[]});x.segments.forEach((s,i)=>{normalizeBase(s);s.verse=String(s.verse||s.id?.split('.')[2]||1);s.lineIndex=s.lineIndex||i+1;s.unitType=s.unitType||'colon';s.hebrewTokenIds=(s.hebrewTokenIds||[]).map(canonicalHebrewId);s.tamil=s.tamil||tamilProjection((s.tamilTokenIds||[]).map(canonicalTamilId),s.tamilText||'',s.status,'migration');s.tamil.tokenIds=(s.tamil.tokenIds||[]).map(canonicalTamilId);s.tamil.status=oldStatusToV03(s.tamil.status||s.status);s.english=s.english||{text:s.englishText||'',method:'migration'};delete s.tamilTokenIds;delete s.tamilText;delete s.englishText;delete s.source});x.parallelGroups.forEach(g=>{normalizeBase(g);g.type=parallelTypeToV03(g.type);if(g.confidence)g.confidence=confidenceToV03(g.confidence)});x.components.forEach(c=>{normalizeBase(c);c.hebrewTokenIds=(c.hebrewTokenIds||[]).map(canonicalHebrewId);c.tamil=c.tamil||tamilProjection((c.tamilTokenIds||[]).map(canonicalTamilId),'',c.status,'migration');c.tamil.tokenIds=(c.tamil.tokenIds||[]).map(canonicalTamilId);c.tamil.status=oldStatusToV03(c.tamil.status||c.status);delete c.tamilTokenIds});x.structures.forEach(s=>{normalizeBase(s);s.type=structureTypeToV03(s.type);s.parentId=s.parentId||null});x.notes=x.notes.map((n,i)=>{if(typeof n==='string')n={text:n};normalizeBase(n);n.id=n.id||`N${String(i+1).padStart(3,'0')}`;n.kind=n.kind||'migration';n.targetIds=n.targetIds||[];return n});x.validation=x.validation||{runAt:now(),issues:[]};x.updatedAt=x.updatedAt||now();delete x.sourceVersion;return{state:x,report}}
