s.parallelGroups.forEach(g=>{if((g.lineIds||[]).length<2)add('error','GROUP_INCOMPLETE',`${g.id} has fewer than two segments.`,'parallelGroup',g.id);(g.lineIds||[]).forEach(id=>{if(!segIds.has(id))add('error','GROUP_INCOMPLETE',`${g.id} refers to missing segment ${id}.`,'parallelGroup',g.id)})});
s.components.forEach(c=>{if(!c.parallelGroupId)add('warning','COMPONENT_UNATTACHED',`${c.id} (${c.label}) is not attached to a parallel group.`,'component',c.id);else if(!grpIds.has(c.parallelGroupId))add('error','COMPONENT_UNATTACHED',`${c.id} refers to missing group ${c.parallelGroupId}.`,'component',c.id);(c.hebrewTokenIds||[]).forEach(id=>{if(!hebrewById[id])add('error','COMPONENT_INVALID_TOKEN',`${c.id} refers to missing Hebrew token ${id}.`,'component',c.id)});tamilIds(c).forEach(id=>{if(!tamilById[id])add('error','COMPONENT_INVALID_TOKEN',`${c.id} refers to missing Tamil token ${id}.`,'component',c.id)})});
for(let i=0;i<s.components.length;i++)for(let j=i+1;j<s.components.length;j++){const a=s.components[i],b=s.components[j];if(componentKey(a)!==componentKey(b))continue;if(a.label===b.label)add('warning','COMPONENT_DUPLICATE',`${a.id} and ${b.id} select the same tokens with label ${a.label}.`,'component',b.id);else add('warning','COMPONENT_CONFLICT',`${a.id} (${a.label}) and ${b.id} (${b.label}) select the same tokens.`,'component',b.id)}
const lg={};s.parallelGroups.forEach(g=>(g.lineIds||[]).forEach(id=>(lg[id]||=[]).push(g.id)));Object.entries(lg).filter(([,v])=>v.length>1).forEach(([id,gs])=>add('warning','GROUP_LINE_IN_MULTIPLE_GROUPS',`${id} belongs to multiple groups: ${gs.join(', ')}.`,'segment',id,true));
