  out.structures=old.map((s,i)=>{const legacy=s.id||`legacy-${i+1}`,id='S'+String(i+1).padStart(3,'0');(map[legacy]||=[]).push(id);return{...clone(s),legacyId:legacy,id,revision:1,revisions:[],updatedAt:s.createdAt||now()}});
