const hcol=document.createElement('div');hcol.className='source-col';hcol.innerHTML='<div class="source-label"><span>HEBREW • UHB 2.1.32</span><span>RTL</span></div>';const ht=document.createElement('div');ht.className='hebrew';DATA.hebrew[v].words.forEach(w=>{const sp=document.createElement('span');sp.className='token aligned';sp.dataset.token=w.id;sp.dataset.lang='hebrew';sp.textContent=w.text;if(selection.hebrew.has(w.id))sp.classList.add('selected');if(componentLabels(w.id,'hebrew').length)sp.classList.add('has-component');sp.title='Click for lemma, Strong’s, morphology and Tamil alignment';ht.append(sp,document.createTextNode(' '))});hcol.appendChild(ht);
