function renderStructureSelects(){const opts=sortedSegments().map(s=>`<option value="${s.id}">${esc(shortLine(s.id))} — ${esc((tamilText(s)||hebrewText(s.hebrewTokenIds)).slice(0,50))}</option>`).join(''),a=$('structureStart'),b=$('structureEnd'),p=$('structureParent'),ca=a.value,cb=b.value,cp=p.value;a.innerHTML=opts;b.innerHTML=opts;if([...a.options].some(o=>o.value===ca))a.value=ca;if([...b.options].some(o=>o.value===cb))b.value=cb;p.innerHTML='<option value="">No parent</option>'+state.structures.filter(x=>x.id!==editingStructureId).map(x=>`<option value="${x.id}">${esc(x.label)} · ${esc(x.title)}</option>`).join('');if([...p.options].some(o=>o.value===cp))p.value=cp}
