function editStructure(id){const s=structureById(id);editingStructureId=id;renderStructureSelects();$('structureLabel').value=s.label;$('structureTitle').value=s.title;$('structureType').value=s.type;$('structureStart').value=s.startLineId;$('structureEnd').value=s.endLineId;$('structureParent').value=s.parentId||'';$('structureNote').value=s.note||'';$('structureFormTitle').textContent=`Edit ${id}`;$('saveStructureBtn').textContent='Save structure changes';$('cancelStructureEditBtn').classList.remove('hidden');switchTab('structure')}
function saveStructure(){const label=$('structureLabel').value.trim(),title=$('structureTitle').value.trim();if(!label||!title){toast('Add label and title');return}const segs=sortedSegments(),i=segs.findIndex(s=>s.id===$('structureStart').value),j=segs.findIndex(s=>s.id===$('structureEnd').value);if(i<0||j<0||i>j){toast('End segment must follow start segment');return}const changes={label,title,type:structureTypeToV03($('structureType').value),startLineId:$('structureStart').value,endLineId:$('structureEnd').value,parentId:$('structureParent').value||null,note:$('structureNote').value.trim()};if(editingStructureId){const s=structureById(editingStructureId);if(changes.parentId===s.id){toast('A structure cannot parent itself');return}const was=s.status==='HUMAN_APPROVED';commit(()=>revise(s,changes,'Structure edited'),`${s.id} updated${was?' · Needs discussion':''}`);resetStructureForm();renderAll()}else{const id=nextEntityId('S',state.structures);commit(()=>state.structures.push({id,...changes,...recordBase('HUMAN_MODIFIED','human','editor')}),`${id} added`);resetStructureForm();renderAll()}}
function depthFor(s){let d=0,p=s.parentId,seen=new Set();while(p&&!seen.has(p)){seen.add(p);d++;p=structureById(p)?.parentId;if(d>6)break}return Math.min(d,3)}
function deleteStructure(id){if(!confirm(`Delete ${id}? Children will move to top level.`))return;commit(()=>{state.structures=state.structures.filter(s=>s.id!==id);state.structures.forEach(s=>{if(s.parentId===id){s.parentId=null;s.status='NEEDS_DISCUSSION'}})},`${id} deleted`)}
function renderStructures(){const r=$('structureTree');r.innerHTML='';if(!state.structures.length){r.innerHTML='<p class="muted">No structure units yet.</p>';return}const segs=sortedSegments(),arr=[...state.structures].sort((a,b)=>segs.findIndex(s=>s.id===a.startLineId)-segs.findIndex(s=>s.id===b.startLineId));arr.forEach(s=>{const e=document.createElement('div');e.className='structure-item';e.dataset.depth=depthFor(s);e.innerHTML=`<div class="structure-top"><span class="structure-title">${esc(s.label)} — ${esc(s.title)}</span><span class="pill ${s.status}">${esc(s.type)} · ${esc(STATUS_LABEL[s.status]||s.status)}</span></div><div class="group-lines">${esc(shortLine(s.startLineId))} → ${esc(shortLine(s.endLineId))}${s.parentId?` · parent ${esc(s.parentId)}`:''} · rev ${s.revision||1}</div>${s.note?`<p class="help">${esc(s.note)}</p>`:''}<div class="card-actions"><button data-a="edit">Edit</button><button data-a="HUMAN_MODIFIED">Mark modified</button><button data-a="HUMAN_APPROVED">Approve</button>${s.status==='HUMAN_APPROVED'?'<button data-a="reopen">Reopen</button>':''}${s.revisions?.length?'<button data-a="history">History</button>':''}<button data-a="delete" class="danger-outline">Delete</button></div>`;e.querySelectorAll('button').forEach(b=>b.onclick=()=>{const a=b.dataset.a;if(a==='edit')editStructure(s.id);else if(a==='delete')deleteStructure(s.id);else if(a==='reopen')commit(()=>setStatus(s,'NEEDS_DISCUSSION'),`${s.id} reopened`);else if(a==='history')showHistory('structure',s.id);else commit(()=>setStatus(s,a),`${s.id}: ${STATUS_LABEL[a]}`)});r.appendChild(e)})}
function applyStatus(status){if(!selection.lines.size){toast('Select one or more poetic segments first');return}commit(()=>selection.lines.forEach(id=>{const s=segmentById(id);if(s)setStatus(s,status)}),`Selected segments: ${STATUS_LABEL[status]}`)}
function approveReviewed(){commit(()=>[...state.segments,...state.parallelGroups,...state.components,...state.structures].forEach(x=>{if(x.status==='HUMAN_MODIFIED')x.status='HUMAN_APPROVED'}),'Human-modified annotations approved')}
function approvePsalm(){const issues=validateState(),errors=issues.filter(i=>i.severity==='error'),warnings=issues.filter(i=>i.severity==='warning');if(errors.length){toast(`Cannot approve: ${errors.length} validation error(s)`);switchTab('validation');return}if(warnings.length&&!confirm(`${warnings.length} validation warning(s) remain. Approve anyway?`))return;commit(()=>[...state.segments,...state.parallelGroups,...state.components,...state.structures].forEach(x=>x.status='HUMAN_APPROVED'),'Psalm 1 marked approved')}
function renderValidation(){const e=lastValidation.filter(i=>i.severity==='error').length,w=lastValidation.filter(i=>i.severity==='warning').length,summary=$('validationSummary');summary.innerHTML=`<div class="metric error"><strong>${e}</strong>Errors</div><div class="metric warning"><strong>${w}</strong>Warnings</div><div class="metric ok"><strong>${lastValidation.length?'—':'✓'}</strong>${lastValidation.length?'Review':'Clean'}</div>`;const r=$('validationIssues');r.innerHTML='';if(!lastValidation.length)r.innerHTML='<div class="notice"><strong>Validation clean.</strong> No data-integrity issues detected.</div>';lastValidation.forEach(i=>{const d=document.createElement('div');d.className='validation-item';d.innerHTML=`<span class="severity ${i.severity}">${esc(i.severity)}</span><div><strong>${esc(i.code)}</strong><div class="help">${esc(i.message)}</div></div>${i.entityId?'<button class="small">Go to</button>':''}`;d.querySelector('button')?.addEventListener('click',()=>{if(i.entityType==='component')switchTab('components');else if(i.entityType==='parallelGroup')switchTab('parallelism');else if(i.entityType==='structure')switchTab('structure');else if(i.entityType==='segment'){activeSegmentId=i.entityId;switchTab('segmentation')}});r.appendChild(d)});$('validationBadge').textContent=lastValidation.length;$('validationBadge').classList.toggle('has-issues',lastValidation.length>0)}
function showHistory(type,id){const e=type==='component'?componentById(id):type==='structure'?structureById(id):groupById(id);$('historyTitle').textContent=`${id} · revision ${e.revision||1}`;const r=$('historyBody'),revs=e.revisions||[];r.innerHTML=revs.length?'<div class="history-list"></div>':'<p class="muted">No previous revisions stored.</p>';if(revs.length){const list=r.querySelector('.history-list');revs.forEach((x,i)=>{const d=document.createElement('div');d.className='history-item';d.innerHTML=`<strong>Revision ${x.revision}</strong><div class="help">${esc(x.change||'Saved')} · ${esc(x.at||'')}</div>${type==='component'?`<button class="small" data-r="${i}">Restore as new revision</button>`:''}`;list.appendChild(d)});list.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>restoreComponentRevision(id,+b.dataset.r))}$('historyDialog').showModal()}
function renderDataset(){$('jsonPreview').textContent=JSON.stringify(state,null,2);$('sourceHashes').innerHTML=Object.values(DATA.meta.sources).map(s=>`<div class="hash-item"><strong>${esc(s.label)}</strong><div class="hash">SHA-256 ${esc(s.sha256)}</div></div>`).join('');$('sourceDialogBody').innerHTML=Object.values(DATA.meta.sources).map(s=>`<div class="source-info-row"><strong>${esc(s.label)}</strong><div class="hash">${esc(s.sha256)}</div></div>`).join('')}
function renderProgress(){const done=state.segments.filter(s=>s.status!=='UNREVIEWED').length;$('progressText').textContent=`${done}/${state.segments.length} segments touched · ${state.parallelGroups.length} group(s) · ${state.components.length} component(s) · ${state.structures.length} structure unit(s)`;$('psalmStatus').textContent=STATUS_LABEL[state.psalmStatus]||state.psalmStatus;$('psalmStatus').className=`status-chip ${state.psalmStatus}`;$('approvePsalmBtn').textContent=state.psalmStatus==='approved'?'✓ Psalm approved':'Approve Psalm'}
function exportJson(){validateState();const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='PSA001.annotations.v0.3.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);toast('Annotation JSON exported')}
function showMigrationReport(report,from){$('migrationReport').innerHTML=`<p class="help">Imported into schema v${VERSION}. Source Scripture remains unchanged.</p><div class="migration-list">${(report.length?report:[{kind:'ok',text:`v${from||VERSION} data loaded without migration.`}]).map(x=>`<div class="migration-item ${x.kind||'ok'}">${esc(x.text)}</div>`).join('')}</div><p class="help">Open Validation for remaining data-quality issues.</p>`;$('migrationDialog').showModal()}
function importJson(file){const rd=new FileReader();rd.onload=()=>{try{const x=JSON.parse(rd.result);if(x.book!=='PSA'||+x.psalm!==1)throw Error('Not Psalm 1 annotation JSON');const v=String(x.schemaVersion||''),result=v.startsWith('0.1')?migrateV01(x):v==='0.2.0'?migrateV02(x):v===VERSION?normalizeV03(x):(()=>{throw Error(`Unsupported schema: ${x.schemaVersion||'unknown'}`)})();state=result.state;recomputePsalmStatus();persist();history=[clone(state)];historyIndex=0;activeGroupId=state.parallelGroups[0]?.id||null;editingComponentId=editingParallelId=editingStructureId=activeSegmentId=null;selection={lines:new Set(),hebrew:new Set(),tamil:new Set(),focus:null};renderAll();showMigrationReport(result.report,x.schemaVersion);toast(`Annotations imported as v${VERSION}`)}catch(e){toast('Import failed: '+e.message)}};rd.readAsText(file)}
async function copyJson(){try{await navigator.clipboard.writeText(JSON.stringify(state,null,2));toast('JSON copied')}catch{toast('Clipboard unavailable; use Export')}}
function bind(){document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('undoBtn').onclick=undo;$('redoBtn').onclick=redo;$('exportBtn').onclick=exportJson;$('importInput').onchange=e=>{if(e.target.files[0])importJson(e.target.files[0]);e.target.value=''};$('clearSelectionBtn').onclick=clearSelection;$('activeGroupSelect').onchange=e=>{activeGroupId=e.target.value||null;renderAll()};$('quickCreateGroupBtn').onclick=openQuickGroup;$('confirmQuickGroupBtn').onclick=createQuickGroup;$('saveComponentBtn').onclick=saveComponentEdit;$('cancelComponentEditBtn').onclick=cancelComponentEdit;$('deleteEditingComponentBtn').onclick=()=>editingComponentId&&deleteComponent(editingComponentId);$('saveParallelBtn').onclick=saveParallel;$('cancelParallelEditBtn').onclick=()=>{resetParallelForm();renderAll()};$('saveStructureBtn').onclick=saveStructure;$('cancelStructureEditBtn').onclick=()=>{resetStructureForm();renderAll()};$('componentFilter').onchange=renderComponents;$('refreshValidationBtn').onclick=()=>{validateState();renderValidation();toast('Validation refreshed')};$('approveReviewedBtn').onclick=approveReviewed;$('approvePsalmBtn').onclick=approvePsalm;$('copyJsonBtn').onclick=copyJson;$('sourceInfoBtn').onclick=()=>$('sourceDialog').showModal();document.querySelectorAll('[data-status-action]').forEach(b=>b.onclick=()=>applyStatus(b.dataset.statusAction));document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}})}
if(window.location?.search?.includes('test=1')){window.__TPE_TEST__={getState:()=>clone(state),setActiveGroup:id=>{activeGroupId=id;renderAll()},setLineSelection:ids=>{selection.lines=new Set(ids);renderAll()},setTokenSelection:(h,t)=>{selection.hebrew=new Set((h||[]).map(canonicalHebrewId));selection.tamil=new Set((t||[]).map(canonicalTamilId));renderAll()},createComponentDirect:label=>createComponent(label),startEditComponent,saveComponentEdit,setEditingLabel:l=>{editingComponentLabel=l;renderComponentButtons()},setComponentStatus:(id,s)=>{const c=componentById(id);commit(()=>setStatus(c,s),`test status ${s}`)},assignSegmentToken,createQuickGroup,deleteParallel,saveStructure,restoreComponentRevision,validateState,setQuickGroupFields:(type,confidence,note)=>{$('quickParallelType').value=type;$('quickParallelConfidence').value=confidence;$('quickParallelNote').value=note||''}}}
